internal static class P5Tests
{
    public static IEnumerable<(string, Func<Task>)> Cases()
    {
        yield return ("p5.pipe.message-boundary-status", PipeMessageStatus);
        yield return ("p5.enum.dispose-error-cleans-open", CursorDispose);
        foreach(var n in new[]{0,23,24,37,38,39})yield return ($"p5.supplement.stream-size-{n}",()=>ListSize(true,n));
        foreach(var n in new[]{0,7,8,10,11,22,23,24})yield return ($"p5.supplement.ea-size-{n}",()=>ListSize(false,n));
        foreach(var cls in new[]{(1,9,32),(1,18,128),(2,1,28),(2,5,18)}) foreach(var delta in new[]{-1,0,1})
            yield return ($"p5.supplement.exact-variable-{cls.Item1}-{cls.Item2}-{delta}",()=>ExactVariable((byte)cls.Item1,(byte)cls.Item2,cls.Item3,delta));
        yield return ("p5.supplement.metadata-process-restart", MetadataRestart);
        yield return ("p5.supplement.allocation-error-capability", AllocationFailure);
        yield return ("p5.supplement.read-zero-short-eof", ReadBoundaries);
        yield return ("p5.supplement.local-disk-through", DiskThrough);
        yield return ("p5.stress.copy-enum-resources", Stress);
        foreach(var n in new[]{0,1,4,5,6}) yield return ($"p5.supplement.pipe-bound-{n}",()=>PipeBoundary(n));
        foreach(var c in new[]{(1,9,4,28),(1,18,100,124),(2,1,18,28),(2,5,12,18)})
            foreach(var delta in new[]{1,2,3}) yield return ($"p5.supplement.query-variable-{c.Item1}-{c.Item2}-{delta}",()=>VariableBoundary((byte)c.Item1,(byte)c.Item2,c.Item3,delta));
        yield return ("p5.copy.concurrent-key", ConcurrentKey);
        yield return ("p5.enum.extended-unavailable", ExtendedEnum);
        yield return ("p5.ioctl.ranges-partial", RangesPartial);
        yield return ("p5.ioctl.reparse-partial", ReparsePartial);
        yield return ("p5.query.ea-resume", EaResume);
        yield return ("p5.query.ea-name-list", EaNames);
        yield return ("p5.query.ea-index", EaIndex);
        yield return ("p5.query.ea-index-out-of-range", EaBadIndex);
        yield return ("p5.ioctl.resume-key-short", ResumeShort);
        yield return ("p5.ioctl.snapshot-short", SnapshotShort);
        yield return ("p5.metadata.change-time-declined", ChangeTime);
        yield return ("p5.write.options-preserved", ()=>WriteOptions(false));
        yield return ("p5.write.versioning-options", ()=>WriteOptions(true));
        yield return ("p5.metadata.volume-size", VolumeSize);
        yield return ("p5.enum.versioning-bounded", VersionEnum);
        foreach (var kind in new[]{"success","source-lock","target-lock","closed-key","partial","partial-write","partial-exception","append","malformed","zero-chunk","source-eof","overlap","source-close","target-close","bounds","coherency"})
            yield return ("p5.copy."+kind,()=>Copy(kind));
        yield return ("p5.io.coherency-hook", IoHook);
        yield return ("p5.enum.invalid-class", EnumInvalid);
        yield return ("p5.metadata.filesystem-name", FsName);
        yield return ("p5.pending.witness-bound", WitnessBound);
        foreach (var write in new[]{false,true}) foreach (var dialect in new[]{SmbDialect.Smb300,SmbDialect.Smb302,SmbDialect.Smb311})
            foreach (var channel in new uint[]{1,2,3,99}) yield return ($"p5.channel.{write}-{dialect}-{channel}",()=>Channel(write,dialect,channel));
        yield return ("p5.local.stream-through-declined", StreamThrough);
        yield return ("p5.pipe.queued-messages", PipeQueue);
        yield return ("p5.enum.bounded-resume", EnumBounded);
        yield return ("p5.enum.reopen-pattern", ()=>EnumReopen());
        yield return ("p5.enum.restart-pattern", ()=>EnumReopen(1));
        yield return ("p5.enum.matching-case", EnumCase);
        yield return ("p5.query.stream-complete-records", StreamBounds);
        yield return ("p5.query.ea-complete-records", EaBounds);
        yield return ("p5.read.minimum", ReadMinimum);
        yield return ("p5.read.max-size", ()=>MaxSize(false));
        yield return ("p5.write.max-size", ()=>MaxSize(true));
        yield return ("p5.write.through-requires-create-option", WriteInvalidThrough);
        yield return ("p5.write.through-flush-error", WriteFlush);
        yield return ("p5.write.channel-data-offset", WriteOffset);
        yield return ("p5.pipe.read-remainder", PipeRead);
        yield return ("p5.pipe.transceive-remainder", PipeIoctl);
        yield return ("p5.pipe.flags", PipeFlags);
        foreach (var n in new[]{0,7,8,9}) yield return ($"p5.allocation.length-{n}",()=>Allocation(n,1,n==8?0xc00000bbu:0xc0000004u));
        foreach (var n in new[]{-1L,long.MaxValue}) yield return ($"p5.allocation.value-{n}",()=>Allocation(8,n,0xc000000du));
        foreach (var c in new[]{(4,40),(5,24),(6,8),(7,4),(14,8),(34,56),(35,8),(18,100),(9,4)})
            foreach (var n in new[]{0,c.Item2-1,c.Item2}) yield return ($"p5.query.file-{c.Item1}-{n}",()=>Query(1,c.Item1,c.Item2,n,c.Item1 is 18 or 9));
        foreach (var c in new[]{(1,18),(3,24),(7,32),(4,8),(5,12)})
            foreach (var n in new[]{0,c.Item2-1,c.Item2}) yield return ($"p5.query.fs-{c.Item1}-{n}",()=>Query(2,c.Item1,c.Item2,n,c.Item1 is 1 or 5));
    }






    static async Task CursorDispose() {var store=new OptionsStore();await using var d=new P2Tests.Direct(store);var id=await Dir(d);Status(await d.Send(EnumPacket(id,"*")),0,"cursor page");var b=await d.Send(RawSmb.Close(id,0,1,42));Status(b,0xc000000d,"fallible cursor close reports error");Check.Equal(0,store.ActiveHandles,"cursor disposal failure still closes backend handle");Check.Equal(0L,d.Options.Metrics.OpenHandles,"cursor disposal failure balances metrics");Check.That(d.Session.Opens.IsEmpty,"cursor disposal failure removes open");}
    static async Task PipeMessageStatus(){await using var d=new P2Tests.Direct();var id=await Pipe(d);d.Session.Opens[id].Pipe!.Transceive([1]);d.Session.Opens[id].Pipe!.Transceive([2]);var b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Status(b,0,"a complete message succeeds even when another message is queued");Check.Equal(5u,RawSmb.U32(b,68),"one message returned");b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Status(b,0,"second message retained");Check.Equal(5u,RawSmb.U32(b,68),"second message complete");}
    static async Task ExactVariable(byte type,byte cls,int full,int delta) {await using var d=new P2Tests.Direct();var id=await d.Open("long-file-name");var b=await d.Send(QueryPacket(id,type,cls,(uint)(full+delta)));Status(b,delta<0?0x80000005u:0,"exact variable-size boundary");Check.Equal((uint)Math.Min(full,full+delta),RawSmb.U32(b,68),"exact-size output count");}
    static async Task ListSize(bool stream,int n) {using var r=new Root();var store=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(store);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;if(!stream)await store.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0),new ExtendedAttribute("y",new byte[]{2},0)]);var b=await d.Send(QueryPacket(id,1,stream?(byte)22:(byte)15,(uint)n));var status=stream?(n<24?0xc0000004u:n<38?0x80000005u:0u):(n<8?0xc0000004u:n<11?0xc0000023u:n<23?0x80000005u:0u);Status(b,status,"list class-specific zero/short/exact status");if(status is 0 or 0x80000005)Check.Equal(stream?(n<38?0u:38u):(n<23?11u:23u),RawSmb.U32(b,68),"only complete records");}
    static async Task AllocationFailure() {var store=new OptionsStore();await using var d=new P2Tests.Direct(store);var id=await d.Open();var data=new byte[8];RawSmb.Put64(data,0,4097);Status(await d.Send(SetPacket(id,19,data)),0xc000007f,"allocation DiskFull forwarded");Check.Equal(1,store.AllocationCalls,"explicit capability invoked");store.AllocationStatus=NtStatus.InvalidDeviceRequest;Status(await d.Send(SetPacket(id,19,data)),0xc0000010,"allocation backend error forwarded");}
    static async Task ReadBoundaries() {await using var d=new P2Tests.Direct();d.Store.Seed("a",[1,2]);var id=await d.Open();var b=await d.Send(RawSmb.Read(id,0,99,0,1,42));Status(b,0,"zero read at EOF succeeds");Check.Equal(0u,RawSmb.U32(b,68),"zero bytes");b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Status(b,0,"short read with minimum zero");Check.Equal(2u,RawSmb.U32(b,68),"short length exact");Status(await d.Send(RawSmb.Read(id,1,2,0,1,42)),0xc0000011,"nonzero EOF");}
    static async Task PipeBoundary(int n) {await using var d=new P2Tests.Direct();var id=await Pipe(d);var b=await d.Send(Ioctl(id,0x11c017,[1],(uint)n));Status(b,n<5?0x80000005u:0,"pipe status boundary");Check.Equal((uint)Math.Min(n,5),RawSmb.U32(b,100),"pipe output count");if(n<5){b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Check.That(b.AsSpan(80).SequenceEqual(new byte[]{10,11,12,13,14}.AsSpan(n)),"all unread bytes preserved");}}
    static async Task VariableBoundary(byte type,byte cls,int minimum,int delta) {await using var d=new P2Tests.Direct();var id=await d.Open("long-file-name");var b=await d.Send(QueryPacket(id,type,cls,(uint)(minimum+delta)));Status(b,0x80000005,"variable portion overflows");Check.Equal((uint)(minimum+delta),RawSmb.U32(b,68),"bounded variable bytes");}
    static async Task DiskThrough() {using var r=new Root();await using var d=new P2Tests.Direct(new LocalFileStore(r.Path,false));var create=d.Create();RawSmb.Put32(create,104,0x48);var c=await d.Send(create);var id=(RawSmb.U64(c,128),RawSmb.U64(c,136));Dialect(d,SmbDialect.Smb210);var b=RawSmb.Write(id,[7,8],0,0,1,42);RawSmb.Put32(b,108,1);Status(await d.Send(b),0,"local disk write-through flush succeeds");Check.That(NativeHost.ReadAllBytes(r.Path+"/a").SequenceEqual(new byte[]{7,8}),"host sees stored bytes");}
    public static async Task MetadataChild(string mode,string root)
    {
        var store=new LocalFileStore(root,false);using var file=(await store.CreateAsync("base",FileAccessIntent.ReadWrite,CreateDispositionIntent.OpenIf,false,true)).Value.Handle;
        if(mode=="write") {await store.WriteAsync(file,0,new byte[]{7,8});using var stream=(await store.OpenNamedStreamAsync("base","alt",FileAccessIntent.ReadWrite,CreateDispositionIntent.OpenIf)).Value.Handle;await store.WriteAsync(stream,0,new byte[]{42});await store.SetExtendedAttributesAsync(file,[new ExtendedAttribute("ea",new byte[]{43},0)]);await store.SetBasicInfoAsync(file,new Smb.Protocol.Messages.FileBasicInfoUpdate{LastWriteTime=new DateTime(2020,1,2,3,4,5,DateTimeKind.Utc).ToFileTimeUtc()});await store.FlushAsync(file);}
        else {Check.That(NativeHost.ReadAllBytes(root+"/base").SequenceEqual(new byte[]{7,8}),"base data survives restart");Check.Equal(0,(await store.GetExtendedAttributesAsync(file)).Value!.Count,"EAs explicitly process-memory only");Check.Equal(NtStatus.ObjectNameNotFound,(await store.OpenNamedStreamAsync("base","alt",FileAccessIntent.Read,CreateDispositionIntent.Open)).Status,"named streams explicitly process-memory only");Check.Equal(new DateTime(2020,1,2,3,4,5,DateTimeKind.Utc).ToFileTimeUtc(),file.GetInfo().LastWriteTime,"host last-write timestamp survives restart");}
    }
    static async Task MetadataRestart() {using var r=new Root();foreach(var mode in new[]{"write","read"}){var info=new System.Diagnostics.ProcessStartInfo(Environment.ProcessPath!){RedirectStandardOutput=true,RedirectStandardError=true};if(System.IO.Path.GetFileNameWithoutExtension(Environment.ProcessPath)=="dotnet")info.ArgumentList.Add(System.IO.Path.Combine(AppContext.BaseDirectory,"Smb.Tests.dll"));info.ArgumentList.Add("--p5-metadata-child");info.ArgumentList.Add(mode);info.ArgumentList.Add(r.Path);using var p=System.Diagnostics.Process.Start(info)!;var stdout=p.StandardOutput.ReadToEndAsync();var stderr=p.StandardError.ReadToEndAsync();await p.WaitForExitAsync().WaitAsync(Check.Timeout);Check.Equal(0,p.ExitCode,"child restart: "+await stdout+await stderr);}}
    static async Task Stress() {for(var i=0;i<32;i++){await using var d=new P2Tests.Direct();CopyPolicy(d);d.Store.Seed("a",[1,2,3]);var src=await d.Open("a");var dst=await d.Open("b");var key=await Key(d,src);Status(await d.Send(CopyPacket(dst,key,(0,0,3))),0,"stress copy");await d.Send(RawSmb.TreeDisconnect(0,1,42));Check.Equal(0,d.Store.ActiveHandles,"stress handles");Check.That(d.Session.Opens.IsEmpty && d.Connection.PendingRequests.IsEmpty && d.Connection.OrdinaryRequests.IsEmpty,"stress request maps");Check.Equal(0L,d.Options.Metrics.OpenHandles,"stress metric count");Check.Equal(0,((Smb.Server.Locking.InMemoryLockManager)d.Options.LockManager).ActiveLockCount,"stress locks");}}
    static async Task ConcurrentKey() {await using var d=new P2Tests.Direct();CopyPolicy(d);var id=await d.Open();d.Connection.Credits.Grant(1024);for(var iteration=0;iteration<32;iteration++){d.Session.Opens[id].ResumeKey=null;var ready=new TaskCompletionSource(TaskCreationOptions.RunContinuationsAsynchronously);var tasks=Enumerable.Range(0,32).Select(_=>Task.Run(async()=>{await ready.Task;return await Key(d,id);})).ToArray();ready.SetResult();var keys=await Task.WhenAll(tasks).WaitAsync(Check.Timeout);Check.Equal(1,keys.Select(Convert.ToHexString).Distinct().Count(),"all simultaneous replies identify the same open lifetime");}}
    static async Task ExtendedEnum(){await using var d=new P2Tests.Direct();var id=await Dir(d);var q=EnumPacket(id,"*");q[66]=60;Status(await d.Send(q),0xc00000bb,"known extended enumeration class unsupported");}
    static async Task VolumeSize() {using var r=new Root();await using var d=new P2Tests.Direct(new LocalFileStore(r.Path,false));var id=await d.Open();var b=await d.Send(QueryPacket(id,2,3,24));var total=NativeHost.VolumeTotalBytes(r.Path);Check.Equal((ulong)(total/4096),RawSmb.U64(b,72),"local volume reports host total rather than synthetic capacity");}

    static async Task RangesPartial() {await using var d=new P2Tests.Direct(new OptionsStore());var id=await d.Open();var data=new byte[16];RawSmb.Put64(data,8,16);var b=await d.Send(Ioctl(id,0x940cf,data,17));Status(b,0x80000005,"allocated ranges partial is overflow");Check.Equal(16u,RawSmb.U32(b,100),"whole range records only");}
    static async Task ReparsePartial() {await using var d=new P2Tests.Direct(new OptionsStore());var id=await d.Open();var b=await d.Send(Ioctl(id,0x900a8,[],12));Status(b,0x80000005,"partial reparse data is overflow");Check.Equal(12u,RawSmb.U32(b,100),"reparse partial bounded");}

    static async Task EaNames() {using var r=new Root();var s=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(s);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;await s.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0),new ExtendedAttribute("y",new byte[]{2},0)]);var q=QueryPacket(id,1,15,100);Array.Resize(ref q,110);RawSmb.Put16(q,72,104);RawSmb.Put32(q,76,6);q[108]=1;q[109]=(byte)'y';Array.Resize(ref q,111);RawSmb.Put32(q,76,7);var b=await d.Send(q);Status(b,0,"EA name list selects");Check.Equal(11u,RawSmb.U32(b,68),"only requested EA");Check.Equal((byte)'y',b[80],"requested name");}
    static async Task EaBadIndex() {using var r=new Root();var s=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(s);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;await s.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0)]);var q=QueryPacket(id,1,15,100);RawSmb.Put32(q,80,uint.MaxValue);RawSmb.Put32(q,84,4);Status(await d.Send(q),0xc0000051,"out of range EA index fails explicitly");}
    static async Task EaIndex() {using var r=new Root();var s=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(s);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;await s.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0),new ExtendedAttribute("y",new byte[]{2},0)]);var q=QueryPacket(id,1,15,100);RawSmb.Put32(q,80,2);RawSmb.Put32(q,84,4);var b=await d.Send(q);Status(b,0,"EA index selection");Check.Equal((byte)'y',b[80],"1 based index");}
    static async Task EaResume() {using var r=new Root();var s=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(s);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;await s.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0),new ExtendedAttribute("y",new byte[]{2},0)]);var q=QueryPacket(id,1,15,11);RawSmb.Put32(q,84,2);var first=await d.Send(q);Status(first,0,"single EA success");var second=await d.Send(q);Status(second,0,"EA resumes on next call");Check.Equal((byte)'y',second[80],"EA cursor advances past first entry");}
    static async Task ResumeShort() {await using var d=new P2Tests.Direct();CopyPolicy(d);var id=await d.Open();Status(await d.Send(Ioctl(id,0x140078,[],31)),0xc000000d,"resume key requires fixed 32 byte output");}
    static async Task SnapshotShort() {await using var d=new P2Tests.Direct(new Smb.FileSystem.Versioning.VersioningFileStore(new FakeFileStore()));var id=await d.Open();Status(await d.Send(Ioctl(id,0x144064,[],15)),0xc000000d,"snapshot requires minimum 16");}
    static async Task ChangeTime() {using var r=new Root();var s=new LocalFileStore(r.Path,false);using var h=(await s.CreateAsync("a",FileAccessIntent.ReadWrite,CreateDispositionIntent.OpenIf,false,true)).Value.Handle;Check.Equal(NtStatus.NotSupported,await s.SetBasicInfoAsync(h,new Smb.Protocol.Messages.FileBasicInfoUpdate{ChangeTime=DateTime.UtcNow.AddDays(-1).ToFileTimeUtc()}),"host cannot set independent change time");}
    static async Task WriteOptions(bool wrapper) {var probe=new OptionsStore();await using var d=new P2Tests.Direct(wrapper?new Smb.FileSystem.Versioning.VersioningFileStore(probe):probe);var b=d.Create();RawSmb.Put32(b,104,0x48);var c=await d.Send(b);var id=(RawSmb.U64(c,128),RawSmb.U64(c,136));Dialect(d,SmbDialect.Smb302);b=RawSmb.Write(id,[1],0,0,1,42);RawSmb.Put32(b,108,3);RawSmb.Put32(b,100,1234);Status(await d.Send(b),0,"options write");Check.That(probe.Last.WriteThrough && probe.Last.Unbuffered && probe.Last.RemainingBytes==1234,"all intentions reach backend");}
    // A backend test adapter; no independent durability claim.
    sealed class OptionsStore:IFileStore,ISparseFileStore,IReparsePointStore,IAllocationFileStore,IDirectoryCursorStore
    {
        public int ActiveHandles=>inner.ActiveHandles;
        public ValueTask<FileStoreResult<IDirectoryCursor>> OpenDirectoryCursorAsync(IFileHandle h,string pattern,CancellationToken c=default) => new ValueTask<FileStoreResult<IDirectoryCursor>>(FileStoreResult<IDirectoryCursor>.Ok(new ThrowingCursor()));
        sealed class ThrowingCursor:IDirectoryCursor {public ValueTask<FileStoreResult<BoundedDirectoryListing>> ReadAsync(int max,CancellationToken c=default) => new ValueTask<FileStoreResult<BoundedDirectoryListing>>(FileStoreResult<BoundedDirectoryListing>.Ok(new BoundedDirectoryListing([new FileEntryInfo { Name = "x", Attributes = SmbFileAttributes.Normal }], true)));public void Dispose()=>throw new IOException("cursor disposal fault");}
        public NtStatus AllocationStatus=NtStatus.DiskFull;public int AllocationCalls;
        public ValueTask<NtStatus> SetAllocationSizeAsync(IFileHandle h,long n,CancellationToken c=default){AllocationCalls++;return new ValueTask<NtStatus>(AllocationStatus);}
        public ValueTask<NtStatus> SetSparseAsync(IFileHandle h,bool b,CancellationToken c=default) => new ValueTask<NtStatus>(NtStatus.Success);
        public ValueTask<NtStatus> SetZeroDataAsync(IFileHandle h,long o,long n,CancellationToken c=default) => new ValueTask<NtStatus>(NtStatus.Success);
        public ValueTask<FileStoreResult<IReadOnlyList<Smb.Protocol.Messages.FsctlMessage.FileRange>>> QueryAllocatedRangesAsync(IFileHandle h,long o,long n,CancellationToken c=default) => new ValueTask<FileStoreResult<IReadOnlyList<FsctlMessage.FileRange>>>(FileStoreResult<IReadOnlyList<Smb.Protocol.Messages.FsctlMessage.FileRange>>.Ok([new FsctlMessage.FileRange(0, 4), new FsctlMessage.FileRange(8, 4)]));
        public ValueTask<FileStoreResult<byte[]>> GetReparsePointAsync(IFileHandle h,CancellationToken c=default){var b=new byte[32];RawSmb.Put32(b,0,0x80000021);RawSmb.Put16(b,4,24);return new ValueTask<FileStoreResult<byte[]>>(FileStoreResult<byte[]>.Ok(b));}
        public ValueTask<NtStatus> SetReparsePointAsync(IFileHandle h,byte[] b,CancellationToken c=default) => new ValueTask<NtStatus>(NtStatus.Success);
        public ValueTask<NtStatus> DeleteReparsePointAsync(IFileHandle h,byte[] b,CancellationToken c=default) => new ValueTask<NtStatus>(NtStatus.Success);
        readonly FakeFileStore inner= new FakeFileStore();public FileIoOptions Last;
        public ValueTask<FileStoreResult<FileCreateResult>> CreateAsync(string p,FileAccessIntent a,CreateDispositionIntent d,bool dir,bool file,CancellationToken c=default)=>inner.CreateAsync(p,a,d,dir,file,c);
        public ValueTask<FileStoreResult<int>> ReadAsync(IFileHandle h,long o,Memory<byte> b,CancellationToken c=default)=>inner.ReadAsync(h,o,b,c);
        public ValueTask<FileStoreResult<int>> WriteAsync(IFileHandle h,long o,ReadOnlyMemory<byte> b,CancellationToken c=default)=>inner.WriteAsync(h,o,b,c);
        public ValueTask<FileStoreResult<int>> WriteWithOptionsAsync(IFileHandle h,long o,ReadOnlyMemory<byte> b,FileIoOptions opts,CancellationToken c=default){Last=opts;return inner.WriteAsync(h,o,b,c);}
        public ValueTask<FileStoreResult<IReadOnlyList<FileEntryInfo>>> QueryDirectoryAsync(IFileHandle h,string p,CancellationToken c=default)=>inner.QueryDirectoryAsync(h,p,c);
        public ValueTask<NtStatus> SetEndOfFileAsync(IFileHandle h,long n,CancellationToken c=default)=>inner.SetEndOfFileAsync(h,n,c);
        public ValueTask<NtStatus> RenameAsync(IFileHandle h,string p,bool r,CancellationToken c=default)=>inner.RenameAsync(h,p,r,c);
        public ValueTask<NtStatus> SetDeleteOnCloseAsync(IFileHandle h,bool b,CancellationToken c=default)=>inner.SetDeleteOnCloseAsync(h,b,c);
        public ValueTask<NtStatus> FlushAsync(IFileHandle h,CancellationToken c=default)=>inner.FlushAsync(h,c);
    }
    static async Task VersionEnum() {using var r=new Root();for(var i=0;i<5;i++)File.WriteAllText(r.Path+"/f"+i,"");await using var d=new P2Tests.Direct(new Smb.FileSystem.Versioning.VersioningFileStore(new LocalFileStore(r.Path,false)));d.Options.MaxDirectoryEnumerationEntries=2;var id=await Dir(d);Status(await d.Send(EnumPacket(id,"*")),0,"versioning wrapper preserves resumable local cursor");}
    sealed class IoCoordinator:IFileIoCoordinator
    {
        public List<FileIoRange[]> Calls= new List<FileIoRange[]>(); public int Active;
        public ValueTask<IDisposable> AcquireAsync(IReadOnlyList<FileIoRange> ranges,CancellationToken token=default) {Calls.Add(ranges.ToArray());Active++;return new ValueTask<IDisposable>(new Scope(this));}
        sealed class Scope(IoCoordinator owner):IDisposable {public void Dispose()=>owner.Active--;}
    }
    static void CopyPolicy(P2Tests.Direct d) {var property=typeof(SmbFeaturePolicy).GetProperty("CopyOnly");if(property!=null)d.Options.FeaturePolicy=(SmbFeaturePolicy)property.GetValue(null)!;}
    static async Task<byte[]> Key(P2Tests.Direct d,(ulong P,ulong V) id) {var b=await d.Send(Ioctl(id,0x140078,[],32));Status(b,0,"opt-in resume key");Check.Equal(32u,RawSmb.U32(b,100),"resume response fixed 32 bytes");return b.AsSpan(112,24).ToArray();}
    static byte[] CopyPacket((ulong P,ulong V) id,byte[] key,params (ulong Source,ulong Target,uint Count)[] chunks) {var data=new byte[32+24*chunks.Length];key.CopyTo(data,0);RawSmb.Put32(data,24,(uint)chunks.Length);for(var i=0;i<chunks.Length;i++){var o=32+24*i;RawSmb.Put64(data,o,chunks[i].Source);RawSmb.Put64(data,o+8,chunks[i].Target);RawSmb.Put32(data,o+16,chunks[i].Count);}return Ioctl(id,0x1440f2,data,12);}
    static async Task Copy(string kind)
    {
        await using var d=new P2Tests.Direct();CopyPolicy(d);d.Store.Seed("source",Enumerable.Range(0,100000).Select(i=>(byte)i).ToArray());var src=await d.Open("source");var dst=kind=="overlap"?src:await d.Open("target");var key=await Key(d,src);
        var coord=new IoCoordinator();d.Options.FileIoCoordinator=coord;
        if(kind=="closed-key") {await d.Send(RawSmb.Close(src,0,1,42));Status(await d.Send(CopyPacket(dst,key,(0,0,4))),0xc0000034,"closed source key invalidated");return;}
        if(kind.EndsWith("lock")) {var other=await d.Open(kind=="source-lock"?"source":"target");await d.Options.LockManager.ApplyAsync(d.Session.Opens[other],[new LockElement(0,4,true,false)],true,default);var b=await d.Send(CopyPacket(dst,key,(0,0,4)));Status(b,0xc0000054,"copy respects stable identity range lock");Check.Equal(0,d.Store.Control.Count("Write"),"lock conflict no mutation");return;}
        if(kind=="bounds") {var b=CopyPacket(dst,key,(0,0,4));RawSmb.Put32(b,108,11);Status(await d.Send(b),0xc000000d,"copy output requires 12");return;}
        if(kind is "partial-write" or "partial-exception") {d.Store.MaxWriteCount=2;d.Store.Control.Enqueue("Write",new OperationStep());d.Store.Control.Enqueue("Write",kind=="partial-exception"?new OperationStep(Error:new UnauthorizedAccessException("copy backend failure")):new OperationStep(Status:NtStatus.DiskFull));var b=await d.Send(CopyPacket(dst,key,(0,0,4)));Status(b,kind=="partial-exception"?0xc0000022u:0xc000007fu,"midchunk write fails");Check.Equal((ushort)49,RawSmb.U16(b,64),"copy failure keeps IOCTL counters layout");Check.Equal(0u,RawSmb.U32(b,112),"no complete chunk");Check.Equal(2u,RawSmb.U32(b,116),"partial chunk bytes");Check.Equal(2u,RawSmb.U32(b,120),"total includes partial bytes");return;}
        if(kind=="append") {await d.Send(RawSmb.Write(dst,[99,98],0,0,1,42));var b=await d.Send(CopyPacket(dst,key,(0,ulong.MaxValue,4)));Status(b,0,"append sentinel supported");Check.That(d.Store.Contents("target").SequenceEqual(new byte[]{99,98,0,1,2,3}),"append resolves actual EOF");return;}
        if(kind=="malformed") {var q=CopyPacket(dst,key,(0,0,4));Array.Resize(ref q,q.Length-1);RawSmb.Put32(q,92,55);var b=await d.Send(q);Status(b,0xc000000d,"malformed chunk invalid");Check.Equal((ushort)49,RawSmb.U16(b,64),"malformed copy returns limit response");return;}
        if(kind=="zero-chunk") {var b=await d.Send(CopyPacket(dst,key,(0,0,0)));Status(b,0xc000000d,"zero length chunk invalid");Check.Equal(16u,RawSmb.U32(b,112),"limits response");return;}
        if(kind=="source-eof") {var b=await d.Send(CopyPacket(dst,key,(99999,0,4)));Status(b,0xc0000011,"incomplete source chunk is EOF");return;}
        if(kind=="partial") {d.Store.Control.Enqueue("Write",new OperationStep());d.Store.Control.Enqueue("Write",new OperationStep(Status:NtStatus.DiskFull));var b=await d.Send(CopyPacket(dst,key,(0,0,4),(4,4,70000)));Status(b,0xc000007f,"copy partial failure status");Check.Equal(1u,RawSmb.U32(b,112),"one complete chunk");Check.Equal(0u,RawSmb.U32(b,116),"no bytes in failing chunk");Check.Equal(4u,RawSmb.U32(b,120),"partial totals retained");return;}
        if(kind.EndsWith("close")) {var gate=new AsyncBarrier();d.Store.Control.Enqueue("Read",new OperationStep(Barrier:gate,IgnoreCancellation:true));var task=d.Send(CopyPacket(dst,key,(0,0,4)));await gate.Entered;var closing=d.Send(RawSmb.Close(kind=="source-close"?src:dst,0,1,42));try {Check.That(!closing.IsCompleted,"close drains physical copy refs");Check.That(!d.Store.Handles.First(h=>h.Path==(kind=="source-close"?"source":"target")).IsDisposed,"copy handle alive");} finally {gate.Release();await Task.WhenAll(task,closing).WaitAsync(Check.Timeout);}return;}
        var response=await d.Send(CopyPacket(dst,key,(0,kind=="overlap"?2UL:0UL,70000)));Status(response,0,"copy success");Check.Equal(1u,RawSmb.U32(response,112),"complete chunk count");Check.Equal(70000u,RawSmb.U32(response,120),"copy total");var bytes=d.Store.Contents(kind=="overlap"?"source":"target");Check.That(bytes.AsSpan(kind=="overlap"?2:0,70000).SequenceEqual(Enumerable.Range(0,70000).Select(i=>(byte)i).ToArray()),"copy preserves overlap source bytes");
        if(kind=="coherency") {Check.Equal(1,coord.Calls.Count,"copy has one coordinated operation");Check.Equal(2,coord.Calls[0].Length,"coordinates both identities");Check.That(!coord.Calls[0][0].ForWrite && coord.Calls[0][1].ForWrite,"source read and target write ranges");Check.Equal(0,coord.Active,"physical scope released");}
    }
    static async Task IoHook() {await using var d=new P2Tests.Direct();var id=await d.Open();var c=new IoCoordinator();d.Options.FileIoCoordinator=c;await d.Send(RawSmb.Write(id,[1],0,0,1,42));await d.Send(RawSmb.Read(id,1,0,0,1,42));Check.Equal(2,c.Calls.Count,"ordinary read and write use same hook");Check.Equal(0,c.Active,"ordinary scopes released");}
    static async Task EnumInvalid() {await using var d=new P2Tests.Direct();var id=await Dir(d);var b=EnumPacket(id,"*");b[66]=4;Status(await d.Send(b),0xc0000003,"invalid enumeration class");}
    static async Task FsName() {await using var d=new P2Tests.Direct();var id=await d.Open();var b=await d.Send(QueryPacket(id,2,5,100));Check.That(Encoding.Unicode.GetString(b,84,(int)RawSmb.U32(b,80))!="NTFS","do not claim NTFS backend semantics");}
    static async Task WitnessBound() {await using var d=new P2Tests.Direct{CommitResponses=false};var id=await d.Open();var store=d.State.WitnessRegistrations;var reg=store.Add(d.Connection.ConnectionId,65537,null,null,null,null);d.Session.Opens[id].Pipe=new RpcPipe(new Smb.Server.Witness.WitnessEndpoint(store,d.Connection.ConnectionId,()=>Array.Empty<Smb.Server.Witness.WitnessInterfaceInfo>()));var pdu=new byte[44];pdu[0]=5;pdu[3]=3;pdu[4]=16;RawSmb.Put16(pdu,8,44);RawSmb.Put32(pdu,12,7);RawSmb.Put32(pdu,16,20);RawSmb.Put16(pdu,22,3);reg.ContextHandle().CopyTo(pdu,24);var t=new RecordingTransport();t.Attach(d.Connection);var interim=await d.Send(Ioctl(id,0x11c017,pdu,2));reg.Notifications.Push(new WitnessNotification {Type=Smb.Server.Witness.WitnessNotifyType.ResourceChange,MessageCount=1,MessageBuffer=[1]});await t.SendAsync(interim,false);await t.WaitForSendAsync();await t.WaitForSendAsync();var b=t.Sends.Last().Message;Status(b,0x80000005,"pending Witness honors output bound");Check.Equal(2u,RawSmb.U32(b,100),"bounded Witness output");var rest=await d.Send(RawSmb.Read(id,4096,0,0,1,42));Check.That(RawSmb.U32(rest,68)>0,"Witness unread remainder retained");}
    sealed class Root:IDisposable { public string Path=System.IO.Path.Combine(System.IO.Path.GetTempPath(),"smb-p5-"+Guid.NewGuid().ToString("N"));public Root()=>Directory.CreateDirectory(Path);public void Dispose()=>Directory.Delete(Path,true); }
    static async Task Channel(bool write,SmbDialect dialect,uint channel) {await using var d=new P2Tests.Direct();var id=await d.Open();Dialect(d,dialect);var b=write?RawSmb.Write(id,[1],0,0,1,42):RawSmb.Read(id,1,0,0,1,42);RawSmb.Put32(b,write?96:100,channel);Status(await d.Send(b),0xc000000d,"non-RDMA connection rejects channel before IO");Check.Equal(0,d.Store.Control.Count(write?"Write":"Read"),"no backend access");}
    static async Task StreamThrough() {using var r=new Root();var local=new LocalFileStore(r.Path,false);using var baseFile=(await local.CreateAsync("a",FileAccessIntent.ReadWrite,CreateDispositionIntent.OpenIf,false,true)).Value.Handle;using var h=(await local.OpenNamedStreamAsync("a","s",FileAccessIntent.ReadWrite,CreateDispositionIntent.OpenIf)).Value.Handle;IFileStore store=local;var result=await store.WriteWithOptionsAsync(h,0,new byte[]{1},new FileIoOptions(WriteThrough:true));Check.Equal(NtStatus.NotSupported,result.Status,"process-memory stream cannot flush to disk");Check.Equal(0L,h.GetInfo().EndOfFile,"reject before modifying stream");}
    static Task PipeQueue() {var p=new RpcPipe(new Endpoint());p.Transceive([1]);p.Transceive([2]);Check.Equal(5,p.TakeOutput(8,out var more).Length,"read one complete queued message");Check.That(more,"second message remains");Check.Equal(5,p.TakeOutput().Length,"queue retains second output");return Task.CompletedTask;}
    static byte[] EnumPacket((ulong P,ulong V) id,string pattern,byte flags=0,uint size=100) {var name=Encoding.Unicode.GetBytes(pattern);var b=RawSmb.Header(14,32+name.Length,0,1,42);RawSmb.Put16(b,64,33);b[66]=12;b[67]=flags;RawSmb.Put64(b,72,id.P);RawSmb.Put64(b,80,id.V);RawSmb.Put16(b,88,name.Length>0?(ushort)96:(ushort)0);RawSmb.Put16(b,90,(ushort)name.Length);RawSmb.Put32(b,92,size);name.CopyTo(b,96);return b;}
    static async Task<(ulong P,ulong V)> Dir(P2Tests.Direct d) {var b=await d.Send(RawSmb.Create("",true,0,1,42));Status(b,0,"directory");return(RawSmb.U64(b,128),RawSmb.U64(b,136));}
    static async Task EnumBounded() {using var r=new Root();for(var i=0;i<9;i++)File.WriteAllText(r.Path+"/f"+i,"");await using var d=new P2Tests.Direct(new LocalFileStore(r.Path,false));d.Options.MaxDirectoryEnumerationEntries=2;var id=await Dir(d);var names=new List<string>();for(var i=0;i<15;i++){var b=await d.Send(EnumPacket(id,"*",(byte)(i==0?2:2),40));if(RawSmb.U32(b,8)==0x80000006)break;Status(b,0,"bounded enumeration resumes instead of resource failure");names.AddRange(RawSmb.Names(RawSmb.Buffer(b,RawSmb.U16(b,66),RawSmb.U32(b,68))));}Check.Equal(10,names.Distinct().Count(),"all entries beyond first backend batch including dot");}
    static async Task EnumReopen(byte flag=16) {using var r=new Root();File.WriteAllText(r.Path+"/aa","");File.WriteAllText(r.Path+"/bb","");await using var d=new P2Tests.Direct(new LocalFileStore(r.Path,false));var id=await Dir(d);await d.Send(EnumPacket(id,"aa"));var b=await d.Send(EnumPacket(id,"bb",flag));Status(b,0,"reopen resets EOF");var names=RawSmb.Names(RawSmb.Buffer(b,RawSmb.U16(b,66),RawSmb.U32(b,68)));Check.That(names.SequenceEqual(new[]{"bb"}),"restart uses new search pattern");}
    static async Task EnumCase() {using var r=new Root();File.WriteAllText(r.Path+"/Case","");await using var d=new P2Tests.Direct(new LocalFileStore(r.Path,false));var id=await Dir(d);var response=await d.Send(EnumPacket(id,"case"));Status(response,OperatingSystem.IsWindows()?0u:0xc000000fu,"host case matching excludes unrequested dot entries");if(OperatingSystem.IsWindows())Check.That(RawSmb.Names(RawSmb.Buffer(response,RawSmb.U16(response,66),RawSmb.U32(response,68))).SequenceEqual(new[]{"Case"}),"Windows case-insensitive match keeps host spelling");}
    static async Task StreamBounds() {await using var d=new P2Tests.Direct();var id=await d.Open();var b=await d.Send(QueryPacket(id,1,22,24));Status(b,0x80000005,"stream only complete records on overflow");Check.Equal(0u,RawSmb.U32(b,68),"do not return partial stream name");}
    static async Task EaBounds() {using var r=new Root();var s=new LocalFileStore(r.Path,false);await using var d=new P2Tests.Direct(s);var id=await d.Open();d.Session.Opens[id].GrantedAccess|=8;await s.SetExtendedAttributesAsync(d.Session.Opens[id].LocalOpen!,[new ExtendedAttribute("x",new byte[]{1},0),new ExtendedAttribute("y",new byte[]{2},0)]);var b=await d.Send(QueryPacket(id,1,15,11));Status(b,0x80000005,"EA overflow returns complete first entry");Check.Equal(11u,RawSmb.U32(b,68),"one complete EA");Check.Equal(0u,RawSmb.U32(b,72),"last returned EA terminates chain");}
    internal static void Status(byte[] b,uint s,string why) => Check.Equal(s,RawSmb.U32(b,8),why);
    internal static byte[] QueryPacket((ulong P,ulong V) id,byte type,byte cls,uint size) { var b=RawSmb.Header(16,40,0,1,42);RawSmb.Put16(b,64,41);b[66]=type;b[67]=cls;RawSmb.Put32(b,68,size);RawSmb.Put64(b,88,id.P);RawSmb.Put64(b,96,id.V);return b; }
    internal static byte[] SetPacket((ulong P,ulong V) id,byte cls,byte[] data) {var b=RawSmb.Header(17,32+data.Length,0,1,42);RawSmb.Put16(b,64,33);b[66]=1;b[67]=cls;RawSmb.Put32(b,68,(uint)data.Length);RawSmb.Put16(b,72,96);RawSmb.Put64(b,80,id.P);RawSmb.Put64(b,88,id.V);data.CopyTo(b,96);return b;}
    internal static byte[] Ioctl((ulong P,ulong V) id,uint code,byte[] data,uint max) {var b=RawSmb.Header(11,56+data.Length,0,1,42);RawSmb.Put16(b,64,57);RawSmb.Put32(b,68,code);RawSmb.Put64(b,72,id.P);RawSmb.Put64(b,80,id.V);RawSmb.Put32(b,88,data.Length>0?120u:0);RawSmb.Put32(b,92,(uint)data.Length);RawSmb.Put32(b,108,max);RawSmb.Put32(b,112,1);data.CopyTo(b,120);return b;}
    static async Task MaxSize(bool write) {await using var d=new P2Tests.Direct();d.Store.Seed("a",[1,2]);var id=await d.Open();d.Connection.MaxReadSize=1;d.Connection.MaxWriteSize=1;Status(await d.Send(write?RawSmb.Write(id,[3,4],0,0,1,42):RawSmb.Read(id,2,0,0,1,42)),0xc000000d,"oversized IO rejected before backend");Check.Equal(0,d.Store.Control.Count(write?"Write":"Read"),"no oversized IO submitted");}
    static async Task ReadMinimum() {await using var d=new P2Tests.Direct();d.Store.Seed("a",[1,2]);var id=await d.Open();var b=RawSmb.Read(id,4,0,0,1,42);RawSmb.Put32(b,96,3);Status(await d.Send(b),0xc0000011,"short read below MinimumCount is EOF");}
    static void Dialect(P2Tests.Direct d,SmbDialect dialect) { d.Connection.Dialect=dialect; }
    static async Task WriteInvalidThrough() {await using var d=new P2Tests.Direct();var id=await d.Open();Dialect(d,SmbDialect.Smb210);var b=RawSmb.Write(id,[1],0,0,1,42);RawSmb.Put32(b,108,1);Status(await d.Send(b),0xc000000d,"WRITE_THROUGH requires no intermediate buffering");Check.Equal(0,d.Store.Control.Count("Write"),"reject before mutation");}
    static async Task WriteFlush() {await using var d=new P2Tests.Direct();var b=d.Create();RawSmb.Put32(b,104,0x48);var c=await d.Send(b);var id=(RawSmb.U64(c,128),RawSmb.U64(c,136));Dialect(d,SmbDialect.Smb210);d.Store.Control.Enqueue("Flush",new OperationStep(Status:NtStatus.DiskFull));b=RawSmb.Write(id,[1],0,0,1,42);RawSmb.Put32(b,108,1);Status(await d.Send(b),0xc000007f,"write-through propagates flush failure");Check.Equal(1,d.Store.Control.Count("Flush"),"flush attempted");}
    static async Task WriteOffset() {await using var d=new P2Tests.Direct();var id=await d.Open();var b=new byte[258];RawSmb.Write(id,[1],0,0,1,42).CopyTo(b,0);RawSmb.Put16(b,66,257);b[257]=1;Status(await d.Send(b),0xc000000d,"channel NONE DataOffset maximum 256");Check.Equal(0,d.Store.Control.Count("Write"),"no write");}
    sealed class Endpoint:IRpcEndpoint {public byte[] HandlePdu(ReadOnlySpan<byte> pdu)=>[10,11,12,13,14];}
    static async Task<(ulong P,ulong V)> Pipe(P2Tests.Direct d) {var id=await d.Open();d.Session.Opens[id].Pipe=new RpcPipe(new Endpoint());return id;}
    static async Task PipeRead() {await using var d=new P2Tests.Direct();var id=await Pipe(d);d.Session.Opens[id].Pipe!.Transceive([1]);var b=await d.Send(RawSmb.Read(id,2,0,0,1,42));Status(b,0x80000005,"message remainder signals overflow");Check.Equal(2u,RawSmb.U32(b,68),"bounded pipe READ");b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Status(b,0,"read remainder");Check.That(b.AsSpan(80).SequenceEqual(new byte[]{12,13,14}),"unread bytes retained");}
    static async Task PipeIoctl() {await using var d=new P2Tests.Direct();var id=await Pipe(d);var b=await d.Send(Ioctl(id,0x11c017,[1],2));Status(b,0x80000005,"transceive overflow");Check.Equal(2u,RawSmb.U32(b,100),"bounded IOCTL output");b=await d.Send(RawSmb.Read(id,8,0,0,1,42));Check.That(b.AsSpan(80).SequenceEqual(new byte[]{12,13,14}),"transceive retains remainder");}
    static async Task PipeFlags() {await using var d=new P2Tests.Direct();var id=await Pipe(d);Dialect(d,SmbDialect.Smb302);var b=RawSmb.Write(id,[1],0,0,1,42);RawSmb.Put32(b,108,2);Status(await d.Send(b),0xc000000d,"pipe rejects unbuffered write");}
    static async Task Allocation(int length,long value,uint status) {await using var d=new P2Tests.Direct();var id=await d.Open();var bytes=new byte[length];if(length>=8)System.Buffers.Binary.BinaryPrimitives.WriteInt64LittleEndian(bytes,value);Status(await d.Send(SetPacket(id,19,bytes)),status,"allocation validates or declines explicitly");Check.Equal(0,d.Store.Contents("a").Length,"allocation does not silently resize EOF");}
    static async Task Query(byte type,int cls,int fixedSize,int size,bool variable) {await using var d=new P2Tests.Direct();var id=await d.Open("long-file-name");var b=await d.Send(QueryPacket(id,type,(byte)cls,(uint)size));Status(b,size<fixedSize?0xc0000004u:variable?0x80000005u:0u,"class-specific output status");if(size>=fixedSize)Check.Equal((uint)size,RawSmb.U32(b,68),"response limited to supplied size");}
